package com.encryptiron;

import java.util.ArrayDeque;
import java.util.Queue;

import javax.inject.Inject;
import javax.inject.Singleton;

import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.client.eventbus.Subscribe;

@Singleton
public class PopUpQueue
{
    private static final int RESIZABLE_CLASSIC_LAYOUT = (161 << 16) | 13;
    private static final int RESIZABLE_MODERN_LAYOUT = (164 << 16) | 13;
    private static final int FIXED_CLASSIC_LAYOUT = 35913770;
    private static final int NOTIFICATION_DISPLAY_SCRIPT = 3343;

    private static final int EMPTY_TICKS_BEFORE_NEXT = 2;
    private static final int MAX_TICKS_TO_APPEAR = 5;

    private static final int[] POP_UP_BOXES = {
        InterfaceID.NotificationDisplay.CONTAINER,
        InterfaceID.NotificationDisplay.CONTENT,
    };

    @Value
    private static class PopUp
    {
        String title;
        String description;
    }

    private final Queue<PopUp> pending = new ArrayDeque<>();
    private int emptyTicks = EMPTY_TICKS_BEFORE_NEXT;
    private boolean waitingToAppear;
    private int ticksWaitedToAppear;

    @Inject
    private Client client;

    public void add(String title, String description)
    {
        pending.add(new PopUp(title, description));
        showNextIfIdle();
    }

    public void clear()
    {
        pending.clear();
        emptyTicks = EMPTY_TICKS_BEFORE_NEXT;
        waitingToAppear = false;
    }

    @Subscribe
    public void onGameTick(GameTick gameTick)
    {
        if (isOnScreen())
        {
            emptyTicks = 0;
            waitingToAppear = false;
        }
        else if (waitingToAppear)
        {
            if (++ticksWaitedToAppear >= MAX_TICKS_TO_APPEAR)
            {
                waitingToAppear = false;
                emptyTicks = EMPTY_TICKS_BEFORE_NEXT;
            }
        }
        else
        {
            emptyTicks++;
        }

        showNextIfIdle();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
        {
            clear();
        }
    }

    private boolean isOnScreen()
    {
        for (int boxId : POP_UP_BOXES)
        {
            Widget box = client.getWidget(boxId);
            if (box != null && !box.isHidden() && box.getWidth() > 0 && box.getHeight() > 0)
            {
                return true;
            }
        }
        return false;
    }

    private void showNextIfIdle()
    {
        if (pending.isEmpty() || waitingToAppear || emptyTicks < EMPTY_TICKS_BEFORE_NEXT || isOnScreen())
        {
            return;
        }

        PopUp popUp = pending.poll();

        if (client.getWidget(InterfaceID.NotificationDisplay.UNIVERSE) == null)
        {
            final int componentId = client.isResized()
                    ? client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1
                    ? RESIZABLE_MODERN_LAYOUT
                    : RESIZABLE_CLASSIC_LAYOUT
                    : FIXED_CLASSIC_LAYOUT;

            client.openInterface(componentId, InterfaceID.NOTIFICATION_DISPLAY, WidgetModalMode.MODAL_CLICKTHROUGH);
        }

        client.runScript(NOTIFICATION_DISPLAY_SCRIPT, popUp.getTitle(), popUp.getDescription(), -1);
        waitingToAppear = true;
        ticksWaitedToAppear = 0;
        emptyTicks = 0;
    }
}

package com.encryptiron;

public final class ServerAddress
{
    private static final String SECURE_SCHEME = "https://";
    private static final String SCHEME_SEPARATOR = "://";

    private ServerAddress()
    {
    }

    public static String httpUrl(String configuredServer, String path)
    {
        return baseUrl(configuredServer) + path;
    }

    public static String webSocketUrl(String configuredServer, String path)
    {
        return baseUrl(configuredServer).replaceFirst("^http", "ws") + path;
    }

    private static String baseUrl(String configuredServer)
    {
        String server = configuredServer.trim().replaceAll("/+$", "");
        return server.contains(SCHEME_SEPARATOR) ? server : SECURE_SCHEME + server;
    }
}

package com.encryptiron;

import javax.inject.Inject;

import com.encryptiron.chat.ClanChatService;
import com.encryptiron.chat.ClanRankWidgets;
import com.encryptiron.chat.RankIcons;
import com.encryptiron.rest.MessageHeaderData;
import com.encryptiron.rest.NewCollectionLogEntry;
import com.encryptiron.rest.OnBossKilled;
import com.encryptiron.rest.SendCollectionLog;
import com.encryptiron.rest.SendCombatAchievements;
import com.encryptiron.rest.SendItemDrop;
import com.encryptiron.runs.AdventureLogReader;
import com.encryptiron.runs.CompletedRunTracker;
import com.encryptiron.runs.StatisticBoardReader;
import com.google.inject.Provides;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.PlayerChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
    name = "Valiance",
    description="Valiance clan plugin to help automate events.",
    internalName = "valiance-clan",
    legacyDataDirectory = "valiance"
)
public class ValianceClanPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    public ValianceConfig config;

    @Inject
    public SendCollectionLog sendCollectionLog;

    @Inject
    public SendCombatAchievements sendCombatAchievements;

    @Inject
    public SendItemDrop sendItemDrop;

    @Inject
    public NewCollectionLogEntry newClogEntry;

    @Inject
    public OnBossKilled onBossKilled;

    @Inject
    public CompletedRunTracker completedRunTracker;

    @Inject
    public AdventureLogReader adventureLogReader;

    @Inject
    public StatisticBoardReader statisticBoardReader;

    @Inject
    private PopUpQueue popUpQueue;

    @Inject
    private ClanChatService clanChatService;

    @Inject
    private RankIcons rankIcons;

    @Inject
    private ClanRankWidgets clanRankWidgets;

    @Inject
    private EventBus eventBus;

    @Inject
    private ClientThread clientThread;

    @Provides
    ValianceConfig getConfig(ConfigManager configManager)
    {
        return configManager.getConfig(ValianceConfig.class);
    }

    @Override
    protected void startUp() throws Exception
    {
        eventBus.register(sendCollectionLog);
        eventBus.register(sendCombatAchievements);
        eventBus.register(sendItemDrop);
        eventBus.register(newClogEntry);
        eventBus.register(onBossKilled);
        eventBus.register(completedRunTracker);
        eventBus.register(adventureLogReader);
        eventBus.register(statisticBoardReader);
        eventBus.register(popUpQueue);

        clanChatService.startUp();
        rankIcons.startUp(getPluginDirectory());
        eventBus.register(clanChatService);
        eventBus.register(rankIcons);
        eventBus.register(clanRankWidgets);

        tryLoadPlayer();
    }

    @Override
    protected void shutDown() throws Exception
    {
        eventBus.unregister(sendCollectionLog);
        eventBus.unregister(sendCombatAchievements);
        eventBus.unregister(sendItemDrop);
        eventBus.unregister(newClogEntry);
        eventBus.unregister(onBossKilled);
        eventBus.unregister(completedRunTracker);
        eventBus.unregister(adventureLogReader);
        eventBus.unregister(statisticBoardReader);
        eventBus.unregister(popUpQueue);
        clientThread.invoke(popUpQueue::clear);

        eventBus.unregister(clanChatService);
        eventBus.unregister(rankIcons);
        eventBus.unregister(clanRankWidgets);
        clanChatService.shutDown();
        clanRankWidgets.redrawRanks();

        MessageHeaderData.reset();
        sendCollectionLog.resetNumClogsAccordingToVarp();
    }

    @Subscribe
    public void onPlayerChanged(PlayerChanged playerChanged)
    {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer != null && playerChanged.getPlayer().getId() == localPlayer.getId())
        {
            tryLoadPlayer();
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN ||
            event.getGameState() == GameState.HOPPING)
		{
            MessageHeaderData.reset();
		}
    }

    private void tryLoadPlayer()
    {
        // Keep trying each tick until the client's name is populated.
        clientThread.invokeLater(() -> {
            if (client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null)
            {
                return false;
            }

            // If the player has been logged in, then we will have missed the varp change events that
            // happen during login. So we will manually scan and update our collection log count here.
            sendCollectionLog.updateNumClogsAccordingToVarp();

            // Load the players account data
            MessageHeaderData.setAccountId(client.getAccountHash());
            MessageHeaderData.setAccountType(client.getVarbitValue(VarbitID.IRONMAN));
            MessageHeaderData.setPlayerName(client.getLocalPlayer().getName());

            return true;
        });
    }
}

package com.encryptiron;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(ValianceConfig.GROUP)
public interface ValianceConfig extends Config
{
    String GROUP = "encryptiron";

    @ConfigItem(
        keyName = "chatMessageOnEventItemAccepted",
        name = "Event Accepted Chat Message",
        description = "Puts a message into the users chatbox when an item used in an event was accepted.",
        position = 1
    )
    default boolean chatMessageOnEventItemAccepted()
    {
        return true;
    }

    @ConfigItem(
        keyName = "popupOnEventItemAccepted",
        name = "Event Accepted Pop-up",
        description = "Triggers a pop-up when an item used in an event was accepted.",
        position = 2
    )
    default boolean popupOnEventItemAccepted()
    {
        return true;
    }

    @ConfigItem(
        keyName = "debug",
        name = "Enable debug",
        description = "Adds debug logging to the users chatbox.",
        position = 3
    )
    default boolean debug()
    {
        return false;
    }

    @ConfigItem(
        keyName = "valianceServerUrl",
        name = "Server URL",
        description = "URL to the Valiance Server (don't change).",
        position = 4
    )
    default String valianceServerUrl()
    {
        return "valianceosrs.com";
    }

    @ConfigSection(
        name = "Clan Chat",
        description = "Valiance clan chat, history and event broadcasts.",
        position = 5
    )
    String clanChatSection = "clanChat";

    @ConfigItem(
        keyName = "shareClanChat",
        name = "Share my clan chat",
        description = "Sends the messages you type in the Valiance clan chat to the Valiance server, so members who log in later see them in chat history and staff can review the chat log. Off unless you turn it on.",
        warning = "This feature submits the messages you type in the Valiance clan chat to a 3rd-party server not controlled or verified by RuneLite developers.",
        position = 6,
        section = clanChatSection
    )
    default boolean shareClanChat()
    {
        return false;
    }

    @Range(
        min = 0,
        max = 100
    )
    @ConfigItem(
        keyName = "clanChatHistoryCount",
        name = "Messages on log-in",
        description = "How many recent Valiance clan chat messages to show when you log in. 0 shows none.",
        position = 7,
        section = clanChatSection
    )
    default int clanChatHistoryCount()
    {
        return 10;
    }
}

package com.encryptiron.chat;

import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Pattern;

import javax.inject.Inject;
import javax.inject.Singleton;

import com.encryptiron.ValianceConfig;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatLineBuffer;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.IconID;
import net.runelite.api.MessageNode;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

@Slf4j
@Singleton
public class ClanChatService
{
    public static final String CLAN_NAME = "Valiance";

    private static final int TICKS_OUTSIDE_CLAN_BEFORE_DISCONNECT = 10;

    private static final int TICKS_BETWEEN_CONNECT_ATTEMPTS = 10;

    private static final int MAX_REPORTED_MESSAGE_AGE_SECONDS = 10;

    private static final Pattern NON_ESCAPE_TAG = Pattern.compile("<(?!lt>|gt>)[^>]*>");
    private static final Pattern NON_NAME_CHARACTER = Pattern.compile("[^A-Za-z0-9 _-]");

    private static final String HISTORY_END_MESSAGE = "<col=7f7f7f>End of recent clan chat</col>";

    private static final int MAX_SECONDS_BETWEEN_SAME_LINE = 60;

    private static final String SHARE_CLAN_CHAT_REMINDER =
        "Turn on <col=ffff00>Share my clan chat</col> in the Valiance plugin settings so clanmates who log in later can see your messages.";

    @Inject
    private Client client;

    @Inject
    private ValianceSocket socket;

    @Inject
    private ValianceConfig config;

    @Inject
    private RankIcons rankIcons;

    private int ticksOutsideClan;
    private int ticksUntilConnectAttempt;
    private boolean historyRequestedThisLogin;
    private boolean remindedToShareThisLogin;
    private boolean addingServerLines;

    public void startUp()
    {
        socket.setHandler("welcome", this::onWelcome);
        socket.setHandler("chat_message", this::onServerLine);
    }

    public void shutDown()
    {
        socket.stop();
        ticksOutsideClan = 0;
        ticksUntilConnectAttempt = 0;
        historyRequestedThisLogin = false;
        remindedToShareThisLogin = false;
    }

    public static boolean isValiance(ClanChannel channel)
    {
        return channel != null && CLAN_NAME.equalsIgnoreCase(Text.removeTags(channel.getName()).trim());
    }

    public ChatMessageType broadcastType()
    {
        return isValiance(client.getClanChannel())
            ? ChatMessageType.CLAN_MESSAGE
            : ChatMessageType.CLAN_GUEST_MESSAGE;
    }

    private boolean isInValianceChannel()
    {
        return isValiance(client.getClanChannel()) || isValiance(client.getGuestClanChannel());
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGIN_SCREEN)
        {
            shutDown();
        }
    }

    @Subscribe
    public void onGameTick(GameTick tick)
    {
        if (isInValianceChannel())
        {
            ticksOutsideClan = 0;
            if (!socket.isRunning() && --ticksUntilConnectAttempt <= 0)
            {
                startSocket();
            }
        }
        else if (socket.isRunning() && ++ticksOutsideClan >= TICKS_OUTSIDE_CLAN_BEFORE_DISCONNECT)
        {
            socket.stop();
        }
    }

    private void startSocket()
    {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null || localPlayer.getName() == null)
        {
            return;
        }

        RuneScapeProfileType profileType = RuneScapeProfileType.getCurrent(client);
        if (profileType != RuneScapeProfileType.STANDARD)
        {
            return;
        }

        JsonObject handshake = new JsonObject();
        handshake.addProperty("type", "hello");
        handshake.addProperty("account_hash", Long.toString(client.getAccountHash()));
        handshake.addProperty("rsn", Text.sanitize(localPlayer.getName()));
        handshake.addProperty("profile_type", profileType.name());
        handshake.addProperty("account_type", client.getVarbitValue(VarbitID.IRONMAN));

        if (rankIcons.getRanksVersion() != null)
        {
            handshake.addProperty("ranks_version", rankIcons.getRanksVersion());
        }
        if (rankIcons.getIconsVersion() != null)
        {
            handshake.addProperty("icons_version", rankIcons.getIconsVersion());
        }

        if (!historyRequestedThisLogin)
        {
            handshake.addProperty("history", config.clanChatHistoryCount());
            historyRequestedThisLogin = true;
        }

        ticksUntilConnectAttempt = TICKS_BETWEEN_CONNECT_ATTEMPTS;
        socket.start(handshake);
    }

    private Map<String, List<Integer>> chatboxLineTimesByKey(ChatMessageType... types)
    {
        Map<String, List<Integer>> lines = new HashMap<>();
        for (ChatMessageType type : types)
        {
            ChatLineBuffer buffer = client.getChatLineMap().get(type.getType());
            if (buffer == null)
            {
                continue;
            }

            for (MessageNode node : buffer.getLines())
            {
                if (node != null)
                {
                    lines.computeIfAbsent(plainNameAndMessage(node.getName(), node.getValue()), key -> new ArrayList<>())
                        .add(node.getTimestamp());
                }
            }
        }
        return lines;
    }

    private static String plainNameAndMessage(String name, String message)
    {
        String plainName = name == null ? "" : Text.sanitize(name).toLowerCase(Locale.ROOT);
        String plainMessage = message == null ? "" : Text.removeTags(message);
        return plainName + "\n" + plainMessage;
    }

    private static boolean isAlreadyInChatbox(Map<String, List<Integer>> chatbox, String name, String message, long sentAtMillis)
    {
        List<Integer> times = chatbox.get(plainNameAndMessage(name, message));
        if (times == null)
        {
            return false;
        }

        long sentAt = sentAtMillis / 1000;
        for (int time : times)
        {
            if (Math.abs(time - sentAt) <= MAX_SECONDS_BETWEEN_SAME_LINE)
            {
                return true;
            }
        }
        return false;
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (addingServerLines || !config.shareClanChat())
        {
            return;
        }

        ClanChannel channel;
        if (event.getType() == ChatMessageType.CLAN_CHAT)
        {
            channel = client.getClanChannel();
        }
        else if (event.getType() == ChatMessageType.CLAN_GUEST_CHAT)
        {
            channel = client.getGuestClanChannel();
        }
        else
        {
            return;
        }

        Player localPlayer = client.getLocalPlayer();
        if (!isValiance(channel) || localPlayer == null || localPlayer.getName() == null)
        {
            return;
        }

        if (!Text.sanitize(event.getName()).equalsIgnoreCase(Text.sanitize(localPlayer.getName())))
        {
            return;
        }

        if (Instant.now().getEpochSecond() - event.getTimestamp() > MAX_REPORTED_MESSAGE_AGE_SECONDS)
        {
            return;
        }

        JsonObject chat = new JsonObject();
        chat.addProperty("type", "chat");
        chat.addProperty("message", event.getMessage());
        socket.send(chat);
    }

    private void onWelcome(JsonObject welcome)
    {
        rankIcons.onWelcome(welcome);
        replayHistory(welcome);
        remindToShareClanChat();
    }

    private void remindToShareClanChat()
    {
        if (remindedToShareThisLogin || config.shareClanChat() || !isInValianceChannel())
        {
            return;
        }

        remindedToShareThisLogin = true;
        addingServerLines = true;
        try
        {
            client.addChatMessage(broadcastType(), "", SHARE_CLAN_CHAT_REMINDER, CLAN_NAME);
        }
        finally
        {
            addingServerLines = false;
        }
    }

    private void replayHistory(JsonObject welcome)
    {
        JsonElement historyElement = welcome.get("history");
        if (historyElement == null || !historyElement.isJsonArray())
        {
            return;
        }

        JsonArray history = historyElement.getAsJsonArray();
        if (history.size() == 0 || !isInValianceChannel())
        {
            return;
        }

        ChatMessageType chatType = isValiance(client.getClanChannel())
            ? ChatMessageType.CLAN_CHAT
            : ChatMessageType.CLAN_GUEST_CHAT;

        ChatMessageType serverLineType = broadcastType();
        Map<String, List<Integer>> chatbox = chatboxLineTimesByKey(chatType, serverLineType);
        boolean added = false;

        addingServerLines = true;
        try
        {
            for (JsonElement element : history)
            {
                if (!element.isJsonObject())
                {
                    continue;
                }

                JsonObject entry = element.getAsJsonObject();
                boolean serverLine = "chat_message".equals(ValianceSocket.getString(entry, "type"));
                JsonElement sentAt = entry.get("sent_at");
                if (sentAt != null && sentAt.isJsonPrimitive() && isAlreadyInChatbox(chatbox,
                    serverLine ? "" : ValianceSocket.getString(entry, "rsn"),
                    ValianceSocket.getString(entry, "message"),
                    sentAt.getAsLong()))
                {
                    continue;
                }

                if (serverLine)
                {
                    addServerLine(serverLineType, entry);
                }
                else
                {
                    addReplayedPlayerLine(chatType, entry);
                }
                added = true;
            }

            if (added)
            {
                client.addChatMessage(serverLineType, "", HISTORY_END_MESSAGE, CLAN_NAME);
            }
        }
        finally
        {
            addingServerLines = false;
        }
    }

    private void onServerLine(JsonObject line)
    {
        addingServerLines = true;
        try
        {
            addServerLine(broadcastType(), line);
        }
        finally
        {
            addingServerLines = false;
        }
    }

    private void addServerLine(ChatMessageType type, JsonObject line)
    {
        String message = ValianceSocket.getString(line, "message");
        if (message == null)
        {
            return;
        }

        MessageNode node = client.addChatMessage(type, "", message, CLAN_NAME);
        if (node == null)
        {
            return;
        }

        JsonElement sentAt = line.get("sent_at");
        if (sentAt != null && sentAt.isJsonPrimitive())
        {
            node.setTimestamp((int) (sentAt.getAsLong() / 1000));
        }
    }

    private static String accountTypeIconTag(JsonElement accountType)
    {
        if (accountType == null || !accountType.isJsonPrimitive())
        {
            return "";
        }

        IconID icon;
        switch (accountType.getAsInt())
        {
            case 1:
                icon = IconID.IRONMAN;
                break;
            case 2:
                icon = IconID.ULTIMATE_IRONMAN;
                break;
            case 3:
                icon = IconID.HARDCORE_IRONMAN;
                break;
            case 4:
                icon = IconID.GROUP_IRONMAN;
                break;
            case 5:
                icon = IconID.HARDCORE_GROUP_IRONMAN;
                break;
            case 6:
                icon = IconID.UNRANKED_GROUP_IRONMAN;
                break;
            default:
                return "";
        }
        return "<img=" + icon.getIndex() + ">";
    }

    private void addReplayedPlayerLine(ChatMessageType chatType, JsonObject entry)
    {
        String name = ValianceSocket.getString(entry, "rsn");
        String message = ValianceSocket.getString(entry, "message");
        JsonElement sentAt = entry.get("sent_at");
        if (name == null || message == null || sentAt == null || !sentAt.isJsonPrimitive())
        {
            return;
        }

        String cleanName = NON_NAME_CHARACTER.matcher(Text.removeTags(name)).replaceAll("");
        String cleanMessage = NON_ESCAPE_TAG.matcher(message).replaceAll("");
        if (cleanName.isEmpty() || cleanMessage.isEmpty())
        {
            return;
        }

        String nameWithIcon = accountTypeIconTag(entry.get("account_type")) + cleanName;

        MessageNode node = client.addChatMessage(chatType, nameWithIcon, cleanMessage, CLAN_NAME);
        if (node != null)
        {
            node.setTimestamp((int) (sentAt.getAsLong() / 1000));
        }
    }
}

package com.encryptiron.chat;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.ScriptID;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

@Singleton
public class ClanRankWidgets
{
    private static final Pattern IMG_TAG = Pattern.compile("<img=(\\d+)>");
    private static final String CHANNEL_PREFIX = "[" + ClanChatService.CLAN_NAME + "]";

    private static final int CLAN_RANK_SPRITES_ENUM = 3798;

    private static final int CHAT_LINE_BUILD_SCRIPT = 84;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private RankIcons rankIcons;

    private Set<Integer> clanRankSprites;
    private boolean chatRebuilt;
    private int decoratedRanksRevision = -1;

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event)
    {
        int scriptId = event.getScriptId();
        if (scriptId == ScriptID.BUILD_CHATBOX || scriptId == CHAT_LINE_BUILD_SCRIPT)
        {
            chatRebuilt = true;
        }
        else if (scriptId == ScriptID.CLAN_SIDEPANEL_DRAW)
        {
            decoratePlayerLists();
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        chatRebuilt = true;
    }

    public void redrawRanks()
    {
        clientThread.invokeLater(() ->
        {
            redrawPlayerList(InterfaceID.ClansSidepanel.UNIVERSE);
            redrawPlayerList(InterfaceID.ClansGuestSidepanel.UNIVERSE);
            client.refreshChat();
        });
    }

    private void redrawPlayerList(int panelId)
    {
        Widget panel = client.getWidget(panelId);
        if (panel != null && panel.getOnVarTransmitListener() != null)
        {
            client.runScript(panel.getOnVarTransmitListener());
        }
    }

    @Subscribe
    public void onBeforeRender(BeforeRender event)
    {
        if (chatRebuilt)
        {
            chatRebuilt = false;
            hideChatRankGraphics();
        }
    }

    @Subscribe
    public void onGameTick(GameTick tick)
    {
        hideChatRankGraphics();

        if (rankIcons.getRanksRevision() != decoratedRanksRevision)
        {
            decoratedRanksRevision = rankIcons.getRanksRevision();
            decoratePlayerLists();
        }
    }

    private boolean isClanRankGraphic(Widget widget)
    {
        if (widget.getType() != WidgetType.GRAPHIC)
        {
            return false;
        }

        if (clanRankSprites == null)
        {
            EnumComposition sprites = client.getEnum(CLAN_RANK_SPRITES_ENUM);
            clanRankSprites = new HashSet<>();
            for (int sprite : sprites.getIntVals())
            {
                clanRankSprites.add(sprite);
            }
        }
        return clanRankSprites.contains(widget.getSpriteId());
    }

    private void hideChatRankGraphics()
    {
        Widget area = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
        if (area == null)
        {
            return;
        }

        List<Widget> texts = new ArrayList<>();
        List<Widget> rankGraphics = new ArrayList<>();
        collectTextsAndRankGraphics(area.getDynamicChildren(), texts, rankGraphics);
        collectTextsAndRankGraphics(area.getStaticChildren(), texts, rankGraphics);

        for (Widget graphic : rankGraphics)
        {
            Widget line = findLineTextForGraphic(graphic, texts);
            if (line != null && Text.removeTags(line.getText()).contains(CHANNEL_PREFIX))
            {
                graphic.setHidden(true);
                moveLineIntoHiddenGraphicSpace(graphic, texts);
            }
        }
    }

    private void moveLineIntoHiddenGraphicSpace(Widget graphic, List<Widget> texts)
    {
        if (graphic.getXPositionMode() != WidgetPositionMode.ABSOLUTE_LEFT)
        {
            return;
        }

        List<Widget> rest = new ArrayList<>();
        Widget name = null;
        for (Widget text : texts)
        {
            if (isOnRow(graphic, text)
                && text.getXPositionMode() == WidgetPositionMode.ABSOLUTE_LEFT
                && text.getOriginalX() >= graphic.getOriginalX())
            {
                rest.add(text);
                if (name == null || text.getOriginalX() < name.getOriginalX())
                {
                    name = text;
                }
            }
        }

        if (name == null)
        {
            return;
        }

        int shift = name.getOriginalX() - graphic.getOriginalX();
        if (shift <= 0)
        {
            return;
        }

        for (Widget text : rest)
        {
            text.setOriginalX(text.getOriginalX() - shift);
            text.revalidate();
        }
    }

    private static boolean isOnRow(Widget graphic, Widget text)
    {
        int middle = graphic.getRelativeY() + graphic.getHeight() / 2;
        return middle >= text.getRelativeY() && middle < text.getRelativeY() + text.getHeight();
    }

    private void collectTextsAndRankGraphics(Widget[] children, List<Widget> texts, List<Widget> rankGraphics)
    {
        if (children == null)
        {
            return;
        }

        for (Widget child : children)
        {
            if (child == null)
            {
                continue;
            }
            if (child.getType() == WidgetType.TEXT && !child.isHidden() && child.getText() != null && !child.getText().isEmpty())
            {
                texts.add(child);
            }
            else if (!child.isHidden() && isClanRankGraphic(child))
            {
                rankGraphics.add(child);
            }
        }
    }

    private static Widget findLineTextForGraphic(Widget graphic, List<Widget> texts)
    {
        Widget found = null;
        for (Widget text : texts)
        {
            if (isOnRow(graphic, text))
            {
                if (Text.removeTags(text.getText()).contains(CHANNEL_PREFIX))
                {
                    return text;
                }
                if (found == null)
                {
                    found = text;
                }
            }
        }
        return found;
    }

    private void decoratePlayerLists()
    {
        if (ClanChatService.isValiance(client.getClanChannel()))
        {
            decoratePlayerList(InterfaceID.ClansSidepanel.PLAYERLIST);
        }
        if (ClanChatService.isValiance(client.getGuestClanChannel()))
        {
            decoratePlayerList(InterfaceID.ClansGuestSidepanel.PLAYERLIST);
        }
    }

    private void decoratePlayerList(int listId)
    {
        Widget list = client.getWidget(listId);
        Widget[] children = list == null ? null : list.getChildren();
        if (children == null)
        {
            return;
        }

        for (Widget child : children)
        {
            if (child == null)
            {
                continue;
            }

            if (isClanRankGraphic(child))
            {
                child.setHidden(true);
            }
            else if (child.getType() == WidgetType.TEXT
                && child.getXTextAlignment() == WidgetTextAlignment.LEFT
                && child.getText() != null && !child.getText().isEmpty())
            {
                addRankIconsToPlayerListName(child);
            }
        }
    }

    private void addRankIconsToPlayerListName(Widget name)
    {
        if (name.getXPositionMode() == WidgetPositionMode.ABSOLUTE_RIGHT
            && name.getWidthMode() == WidgetSizeMode.MINUS
            && name.getOriginalWidth() != 0)
        {
            name.setOriginalWidth(0);
            name.revalidate();
        }

        String plainName = IMG_TAG.matcher(name.getText()).replaceAll("");
        name.setText(rankIcons.rankIconTags(plainName) + plainName);
    }
}

package com.encryptiron.chat;

import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.ArrayList;
