import com.encryptiron.rest.OnBossKilled;
import com.encryptiron.rest.SendCompletedRun;
import com.google.common.base.Strings;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;

import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

public class CompletedRunTracker
{
    private static final long SIGHTING_RETENTION_MS = TimeUnit.HOURS.toMillis(6);
    private static final long RUN_WINDOW_MARGIN_MS = 6000;
    private static final int KILL_COUNT_VARP_TICKS_AROUND_LINE = 10;
    private static final int MOST_TICKS_TO_WAIT_FOR_KILL_COUNT_VARP = 3;
    private static final int TICKS_BETWEEN_PRUNES = 100;

    private static final Set<ChatMessageType> GAME_ONLY_MESSAGE_TYPES = EnumSet.of(
        ChatMessageType.GAMEMESSAGE,
        ChatMessageType.SPAM,
        ChatMessageType.FRIENDSCHATNOTIFICATION);

    private static final Pattern TIME = Pattern.compile("(?<![0-9:.])\\d+(?::\\d{2}){1,2}(?:\\.\\d{1,2})?(?![0-9:])");
    private static final Pattern KILL_COUNT = Pattern.compile("Your (?:completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?.+?(?:</col>)? (?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?is: ?(?:<col=[0-9a-f]{6}>|@.+?@)(?<count>[0-9,]+)</col>");
    private static final Pattern PLAYER_NAME = Pattern.compile("[A-Za-z0-9 _-]{1,12}");
    private static final Pattern ONLY_DIGITS = Pattern.compile("[0-9]+");
    private static final Set<String> TIMED_FROM_FIRST_DAMAGE = Set.of(
        "Corporeal Beast",
        "Giant Mole",
        "Kalphite Queen");
    private static final Set<String> TIMED_FROM_SPAWN = Set.of(
        "King Black Dragon",
        "General Graardor",
        "Commander Zilyana",
        "Kree'arra",
        "K'ril Tsutsaroth");
    private static final long MS_PER_TICK = 600;
    private static final int LONGEST_PLUGIN_TIMED_FIGHT_TICKS = 3000;
    private static final int NO_KILL_COUNT = -1;
    private static final Pattern PERSONAL_BEST = Pattern.compile("(?i)personal best");
    private static final Pattern ROOM_DURATION = Pattern.compile("(?i)duration:\\s*(?:<[^>]*>)*\\s*(?<time>\\d+(?::\\d{2}){1,2}(?:\\.\\d{1,2})?)");
    private static final Pattern RAID_ROOM_COMPLETE = Pattern.compile("(?i)^(?:<[^>]*>)*(?:wave '[^']+'.* complete!|challenge complete: )");
    private static final int[] TOB_PARTY_SLOTS = {
        VarbitID.TOB_CLIENT_P0, VarbitID.TOB_CLIENT_P1, VarbitID.TOB_CLIENT_P2, VarbitID.TOB_CLIENT_P3, VarbitID.TOB_CLIENT_P4,
    };
    private static final int[] TOA_PARTY_SLOTS = {
        VarbitID.TOA_CLIENT_P0, VarbitID.TOA_CLIENT_P1, VarbitID.TOA_CLIENT_P2, VarbitID.TOA_CLIENT_P3,
        VarbitID.TOA_CLIENT_P4, VarbitID.TOA_CLIENT_P5, VarbitID.TOA_CLIENT_P6, VarbitID.TOA_CLIENT_P7,
    };
    private static final int[] TFA_PARTY_SLOTS = {
        VarbitID.TFA_CLIENT_P0, VarbitID.TFA_CLIENT_P1, VarbitID.TFA_CLIENT_P2, VarbitID.TFA_CLIENT_P3,
        VarbitID.TFA_CLIENT_P4, VarbitID.TFA_CLIENT_P5, VarbitID.TFA_CLIENT_P6, VarbitID.TFA_CLIENT_P7,
    };

    private static final int[] PARTY_NAME_VARCS = {
        VarClientID.TOB_CLIENT_NAME0,
        VarClientID.TOB_CLIENT_NAME1,
        VarClientID.TOB_CLIENT_NAME2,
        VarClientID.TOB_CLIENT_NAME3,
        VarClientID.TOB_CLIENT_NAME4,
        VarClientID.TOA_CLIENT_NAME0,
        VarClientID.TOA_CLIENT_NAME1,
        VarClientID.TOA_CLIENT_NAME2,
        VarClientID.TOA_CLIENT_NAME3,
        VarClientID.TOA_CLIENT_NAME4,
        VarClientID.TOA_CLIENT_NAME5,
        VarClientID.TOA_CLIENT_NAME6,
        VarClientID.TOA_CLIENT_NAME7,
    };

    @Inject
    private Client client;

    @Inject
    private SendCompletedRun sendCompletedRun;

    @Inject
    private SetupSnapshots setupSnapshots;

    private final Map<String, PlayerSightings> sightingsByPlayerName = new HashMap<>();
    private final Map<String, Integer> pluginTimerStartTickByNpcName = new HashMap<>();
    private final Deque<GameLine> gameLines = new ArrayDeque<>();
    private final Deque<KillCountChange> killCountChanges = new ArrayDeque<>();
    private PendingRun pendingRun;

    @Subscribe
    public void onGameTick(GameTick gameTick)
    {
        int tick = client.getTickCount();
        long nowMs = System.currentTimeMillis();

        recordSightings(nowMs);
        startPluginTimers(tick);
        setupSnapshots.record(nowMs);

        if (pendingRun != null && tick > pendingRun.killCountLine.tick
            && (killCountVarpConfirmsPendingRun() || tick >= pendingRun.killCountLine.tick + MOST_TICKS_TO_WAIT_FOR_KILL_COUNT_VARP))
        {
            sendPendingRun();
        }

        if (tick % TICKS_BETWEEN_PRUNES == 0)
        {
            dropSightingsOlderThan(nowMs - SIGHTING_RETENTION_MS);
        }
    }

    @Subscribe(priority = 1)
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
        {
            sendPendingRun();
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage chatMessage)
    {
        if (!GAME_ONLY_MESSAGE_TYPES.contains(chatMessage.getType())
            || !Strings.isNullOrEmpty(chatMessage.getName())
            || chatMessage.getSender() != null)
        {
            return;
        }

        String message = chatMessage.getMessage();
        Matcher killCountMatcher = KILL_COUNT.matcher(message);
        boolean isKillCountLine = killCountMatcher.find();
        if (!isKillCountLine && !TIME.matcher(message).find())
        {
            return;
        }

        GameLine gameLine = new GameLine(client.getTickCount(), System.currentTimeMillis(), message);
        gameLines.addLast(gameLine);

        if (isKillCountLine)
        {
            if (pendingRun != null && pendingRun.killCountLine.tick != gameLine.tick)
            {
                sendPendingRun();
            }

            String timedNpcName = timedNpcNameIn(message);
            Integer timerStartTick = timedNpcName == null ? null : pluginTimerStartTickByNpcName.remove(timedNpcName);
            if (timerStartTick != null && gameLine.tick - timerStartTick > LONGEST_PLUGIN_TIMED_FIGHT_TICKS)
            {
                timerStartTick = null;
            }

            pendingRun = newPendingRun(
                gameLine,
                Integer.parseInt(killCountMatcher.group("count").replace(",", "")),
                timerStartTick == null ? null : timedNpcName,
                timerStartTick == null ? 0 : (gameLine.tick - timerStartTick) * MS_PER_TICK);
        }
        else if ((PERSONAL_BEST.matcher(message).find() || RAID_ROOM_COMPLETE.matcher(message).find())
            && (pendingRun == null || pendingRun.killCountLine.tick != gameLine.tick))
        {
            if (pendingRun != null)
            {
                sendPendingRun();
            }

            pendingRun = newPendingRun(gameLine, NO_KILL_COUNT, null, 0);
        }
    }

    private PendingRun newPendingRun(GameLine gameLine, int killCount, String pluginTimerNpcName, long pluginTimerMs)
    {
        return new PendingRun(
            gameLine,
            killCount,
            client.getAccountHash(),
            client.getWorld(),
            client.getVarbitValue(VarbitID.TOA_CLIENT_RAID_LEVEL),
            localPlayerName(),
            pluginTimerNpcName,
            pluginTimerMs,
            new int[] {partySize(TOB_PARTY_SLOTS), partySize(TOA_PARTY_SLOTS), partySize(TFA_PARTY_SLOTS)});
    }

    private int partySize(int[] partySlotVarbits)
    {
        int partySize = 0;
        for (int partySlotVarbit : partySlotVarbits)
        {
            if (client.getVarbitValue(partySlotVarbit) > 0)
            {
                partySize++;
            }
        }

        return partySize;
    }

    @Subscribe
    public void onNpcSpawned(NpcSpawned npcSpawned)
    {
        String npcName = timedNpcName(npcSpawned.getNpc().getName(), TIMED_FROM_SPAWN);
        if (npcName != null)
        {
            pluginTimerStartTickByNpcName.put(npcName, client.getTickCount());
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged varbitChanged)
    {
        if (varbitChanged.getVarbitId() != -1 || client.getLocalPlayer() == null)
        {
            return;
        }

        String killCountName = OnBossKilled.bossNameForVarp(varbitChanged.getVarpId());
        if (killCountName == null)
        {
            return;
        }

        killCountChanges.addLast(new KillCountChange(
            client.getTickCount(),
            System.currentTimeMillis(),
            killCountName,
            client.getVarpValue(varbitChanged.getVarpId())));
    }

    private void recordSightings(long nowMs)
    {
        if (client.getLocalPlayer() == null)
        {
            return;
        }

        for (Player player : client.getTopLevelWorldView().players())
        {
            String playerName = cleanName(player.getName());
            if (playerName == null)
            {
                continue;
            }

            PlayerSightings sightings = sightingsOf(playerName);
            sightings.seenPresent(nowMs);

            Actor target = player.getInteracting();
            String targetName = target instanceof NPC ? cleanName(target.getName()) : null;
            if (targetName != null)
            {
                sightings.seenTargeting(targetName, nowMs);
            }
        }

        for (int partyNameVarc : PARTY_NAME_VARCS)
        {
            String partyMemberName = cleanName(client.getVarcStrValue(partyNameVarc));
            if (partyMemberName != null)
            {
                sightingsOf(partyMemberName).seenInParty(nowMs);
            }
        }

        recordChambersPartyPanel(nowMs);
    }

    private void startPluginTimers(int tick)
    {
        for (NPC npc : client.getTopLevelWorldView().npcs())
        {
            String npcName = timedNpcName(npc.getName(), TIMED_FROM_FIRST_DAMAGE);
            if (npcName == null || pluginTimerStartTickByNpcName.containsKey(npcName))
            {
                continue;
            }

            boolean belowFullHealth = npc.getHealthScale() > 0
                && npc.getHealthRatio() > 0
                && npc.getHealthRatio() < npc.getHealthScale()
                && !npc.isDead();
            if (belowFullHealth)
            {
                pluginTimerStartTickByNpcName.put(npcName, tick);
            }
        }
    }

    private static String timedNpcName(String npcName, Set<String> timedNpcNames)
    {
        String cleaned = cleanName(npcName);
        if (cleaned == null)
        {
            return null;
        }

        for (String timedNpcName : timedNpcNames)
        {
            if (timedNpcName.equalsIgnoreCase(cleaned))
            {
                return timedNpcName;
            }
        }

        return null;
    }

    private String timedNpcNameIn(String killCountMessage)
    {
        String text = Text.removeTags(killCountMessage).toLowerCase();
        for (String npcName : pluginTimerStartTickByNpcName.keySet())
        {
            if (text.contains(npcName.toLowerCase()))
            {
                return npcName;
            }
        }

        return null;
    }

    private void recordChambersPartyPanel(long nowMs)
    {
        Widget partyList = client.getWidget(InterfaceID.RaidsSidepanel.LIST);
        if (partyList == null || partyList.isHidden())
        {
            return;
        }

        for (Widget row : partyList.getDynamicChildren())
        {
            String text = cleanName(row.getText());
            if (text != null && PLAYER_NAME.matcher(text).matches() && !ONLY_DIGITS.matcher(text).matches())
            {
                sightingsOf(text).seenInParty(nowMs);
            }
        }
    }

    private boolean killCountVarpConfirmsPendingRun()
    {
        int fromTick = pendingRun.killCountLine.tick - KILL_COUNT_VARP_TICKS_AROUND_LINE;
        return killCountChanges.stream()
            .anyMatch(change -> change.tick >= fromTick && change.count == pendingRun.killCount);
    }

    private void sendPendingRun()
    {
        if (pendingRun == null)
        {
            return;
        }

        PendingRun run = pendingRun;
        pendingRun = null;

        GameLine killCountLine = run.killCountLine;
        long longestCompletionTimeMs = 0;
        for (GameLine gameLine : gameLines)
        {
            if (gameLine.tick == killCountLine.tick)
            {
                longestCompletionTimeMs = Math.max(longestCompletionTimeMs, longestTimeIn(gameLine.message));
            }
        }

        if (longestCompletionTimeMs == 0)
        {
            longestCompletionTimeMs = run.pluginTimerMs;
        }

        if (longestCompletionTimeMs == 0)
        {
            return;
        }

        long endMs = killCountLine.timeMs;
        long startMs = endMs - longestCompletionTimeMs - RUN_WINDOW_MARGIN_MS;

        JsonArray lines = new JsonArray();
        for (GameLine gameLine : gameLines)
        {
            if (gameLine.timeMs >= startMs && gameLine.tick <= killCountLine.tick)
            {
                JsonObject line = new JsonObject();
                line.addProperty("offset_ms", gameLine.timeMs - endMs);
                line.addProperty("tick_offset", gameLine.tick - killCountLine.tick);
                line.addProperty("message", gameLine.message);
                JsonObject roomSetup = roomSetupFor(gameLine);
                if (roomSetup != null)
                {
                    line.add("setup", roomSetup);
                }
                lines.add(line);
            }
        }

        JsonArray killCounts = new JsonArray();
        for (KillCountChange change : killCountChanges)
        {
            if (change.tick >= killCountLine.tick - KILL_COUNT_VARP_TICKS_AROUND_LINE)
            {
                JsonObject killCount = new JsonObject();
                killCount.addProperty("name", change.name);
                killCount.addProperty("count", change.count);
                killCount.addProperty("tick_offset", change.tick - killCountLine.tick);
                killCounts.add(killCount);
            }
        }

        JsonArray players = new JsonArray();
        sightingsByPlayerName.forEach((playerName, sightings) -> {
            JsonObject player = sightings.toJsonWithin(playerName, startMs, endMs);
            if (player != null)
            {
                players.add(player);
            }
        });

        JsonObject varbits = new JsonObject();
        varbits.addProperty("toa_raid_level", run.toaRaidLevel);
        varbits.addProperty("tob_party_size", run.raidPartySizes[0]);
        varbits.addProperty("toa_party_size", run.raidPartySizes[1]);
        varbits.addProperty("tfa_party_size", run.raidPartySizes[2]);

        JsonObject completedRun = new JsonObject();
        completedRun.addProperty("account_hash", String.valueOf(run.accountHash));
        completedRun.addProperty("local_player", run.localPlayerName);
        completedRun.addProperty("world", run.world);
        completedRun.addProperty("kill_count", run.killCount);
        completedRun.add("lines", lines);
        completedRun.add("kill_count_changes", killCounts);
        completedRun.add("varbits", varbits);
        completedRun.add("players", players);

        if (run.pluginTimerNpcName != null)
        {
            JsonObject pluginTimer = new JsonObject();
            pluginTimer.addProperty("npc", run.pluginTimerNpcName);
            pluginTimer.addProperty("duration_ms", run.pluginTimerMs);
            completedRun.add("plugin_timer", pluginTimer);
        }
        completedRun.add("setup", setupSnapshots.setupAt(endMs - longestCompletionTimeMs));

        sendCompletedRun.send(completedRun);
    }

    private void dropSightingsOlderThan(long cutoffMs)
    {
        while (!gameLines.isEmpty() && gameLines.peekFirst().timeMs < cutoffMs)
        {
            gameLines.removeFirst();
        }

        while (!killCountChanges.isEmpty() && killCountChanges.peekFirst().timeMs < cutoffMs)
        {
            killCountChanges.removeFirst();
        }

        setupSnapshots.dropOlderThan(cutoffMs);
        sightingsByPlayerName.values().forEach(sightings -> sightings.dropEndedBefore(cutoffMs));
        sightingsByPlayerName.values().removeIf(PlayerSightings::isEmpty);
    }

    private PlayerSightings sightingsOf(String playerName)
    {
        return sightingsByPlayerName.computeIfAbsent(playerName, name -> new PlayerSightings());
    }

    private String localPlayerName()
    {
        Player localPlayer = client.getLocalPlayer();
        return localPlayer == null ? null : cleanName(localPlayer.getName());
    }

    private static String cleanName(String name)
    {
        if (name == null)
        {
            return null;
        }

        String cleaned = Text.removeTags(name).replace((char) 0xA0, ' ').trim();
        return cleaned.isEmpty() ? null : cleaned;
    }

    private JsonObject roomSetupFor(GameLine gameLine)
    {
        if (!RAID_ROOM_COMPLETE.matcher(gameLine.message).find())
        {
            return null;
        }

        Matcher duration = ROOM_DURATION.matcher(gameLine.message);
        return duration.find() ? setupSnapshots.setupAt(gameLine.timeMs - timeToMs(duration.group("time"))) : null;
    }

    static long longestTimeIn(String message)
    {
        long longestMs = 0;
        Matcher timeMatcher = TIME.matcher(message);
        while (timeMatcher.find())
        {
            longestMs = Math.max(longestMs, timeToMs(timeMatcher.group()));
        }

        return longestMs;
    }

    static long timeToMs(String time)
    {
        String[] parts = time.split(":");
        double seconds = Double.parseDouble(parts[parts.length - 1]);
        long minutes = Long.parseLong(parts[parts.length - 2]);
        long hours = parts.length == 3 ? Long.parseLong(parts[0]) : 0;
        return Math.round(((hours * 60 + minutes) * 60 + seconds) * 1000);
    }

    private static class GameLine
    {
        private final int tick;
        private final long timeMs;
        private final String message;

        private GameLine(int tick, long timeMs, String message)
        {
            this.tick = tick;
            this.timeMs = timeMs;
            this.message = message;
        }
    }

    private static class KillCountChange
    {
        private final int tick;
        private final long timeMs;
        private final String name;
        private final int count;

        private KillCountChange(int tick, long timeMs, String name, int count)
        {
            this.tick = tick;
            this.timeMs = timeMs;
            this.name = name;
            this.count = count;
        }
    }

    private static class PendingRun
    {
        private final GameLine killCountLine;
        private final int killCount;
        private final long accountHash;
        private final int world;
        private final int toaRaidLevel;
        private final String localPlayerName;
        private final String pluginTimerNpcName;
        private final long pluginTimerMs;
        private final int[] raidPartySizes;

        private PendingRun(GameLine killCountLine, int killCount, long accountHash, int world, int toaRaidLevel, String localPlayerName,
            String pluginTimerNpcName, long pluginTimerMs, int[] raidPartySizes)
        {
            this.killCountLine = killCountLine;
            this.killCount = killCount;
            this.accountHash = accountHash;
            this.world = world;
            this.toaRaidLevel = toaRaidLevel;
            this.localPlayerName = localPlayerName;
            this.pluginTimerNpcName = pluginTimerNpcName;
            this.pluginTimerMs = pluginTimerMs;
            this.raidPartySizes = raidPartySizes;
        }
    }
}

package com.encryptiron.runs;

import java.util.HashMap;
import java.util.Map;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;

class PlayerSightings
{
    private final TimeSpans present = new TimeSpans();
    private final TimeSpans inParty = new TimeSpans();
    private final Map<String, TimeSpans> targetedByNpcName = new HashMap<>();

    void seenPresent(long timeMs)
    {
        present.add(timeMs);
    }

    void seenInParty(long timeMs)
    {
        inParty.add(timeMs);
    }

    void seenTargeting(String npcName, long timeMs)
    {
        targetedByNpcName.computeIfAbsent(npcName, name -> new TimeSpans()).add(timeMs);
    }

    void dropEndedBefore(long timeMs)
    {
        present.dropEndedBefore(timeMs);
        inParty.dropEndedBefore(timeMs);
        targetedByNpcName.values().forEach(spans -> spans.dropEndedBefore(timeMs));
        targetedByNpcName.values().removeIf(TimeSpans::isEmpty);
    }

    boolean isEmpty()
    {
        return present.isEmpty() && inParty.isEmpty() && targetedByNpcName.isEmpty();
    }

    JsonObject toJsonWithin(String playerName, long fromMs, long toMs)
    {
        JsonArray presentOffsets = present.toOffsetsWithin(fromMs, toMs);
        JsonArray partyOffsets = inParty.toOffsetsWithin(fromMs, toMs);

        JsonObject targets = new JsonObject();
        targetedByNpcName.forEach((npcName, spans) -> {
            JsonArray targetOffsets = spans.toOffsetsWithin(fromMs, toMs);
            if (targetOffsets.size() > 0)
            {
                targets.add(npcName, targetOffsets);
            }
        });

        if (presentOffsets.size() == 0 && partyOffsets.size() == 0 && targets.size() == 0)
        {
            return null;
        }

        JsonObject json = new JsonObject();
        json.addProperty("name", playerName);
        json.add("present", presentOffsets);
        json.add("party", partyOffsets);
        json.add("targets", targets);
        return json;
    }
}

package com.encryptiron.runs;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Iterator;

import javax.inject.Inject;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;

import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

class SetupSnapshots
{
    private static final int INVENTORY_SIZE = 28;
    private static final int EQUIPMENT_SIZE = 14;
    private static final int[][] RUNE_POUCH_VARBITS = {
        {VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_QUANTITY_1},
        {VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_QUANTITY_2},
        {VarbitID.RUNE_POUCH_TYPE_3, VarbitID.RUNE_POUCH_QUANTITY_3},
        {VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_QUANTITY_4},
    };

    @Inject
    private Client client;

    private final Deque<Snapshot> snapshots = new ArrayDeque<>();

    void record(long nowMs)
    {
        JsonObject setup = currentSetup();
        if (setup == null)
        {
            return;
        }

        String setupText = setup.toString();
        if (!snapshots.isEmpty() && snapshots.peekLast().setupText.equals(setupText))
        {
            return;
        }

        snapshots.addLast(new Snapshot(nowMs, setup, setupText));
    }

    JsonObject setupAt(long timeMs)
    {
        Snapshot chosen = null;
        for (Snapshot snapshot : snapshots)
        {
            if (snapshot.timeMs > timeMs)
            {
                return chosen != null ? chosen.setup : snapshot.setup;
            }
            chosen = snapshot;
        }

        return chosen == null ? null : chosen.setup;
    }

    void dropOlderThan(long cutoffMs)
    {
        while (snapshots.size() > 1 && secondSnapshot().timeMs <= cutoffMs)
        {
            snapshots.removeFirst();
        }
    }

    private Snapshot secondSnapshot()
    {
        Iterator<Snapshot> iterator = snapshots.iterator();
        iterator.next();
        return iterator.next();
    }

    private JsonObject currentSetup()
    {
        ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
        if (inventory == null && equipment == null)
        {
            return null;
        }

        JsonObject setup = new JsonObject();
        setup.add("inv", itemsOf(inventory, INVENTORY_SIZE));
        setup.add("eq", itemsOf(equipment, EQUIPMENT_SIZE));
        setup.add("rp", runePouch());
        setup.addProperty("sb", client.getVarbitValue(VarbitID.SPELLBOOK));

        int quiverAmmo = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);
        int quiverAmount = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT);
        if (quiverAmmo > 0 && quiverAmount > 0)
        {
            JsonArray quiver = new JsonArray();
            quiver.add(item(quiverAmmo, quiverAmount));
            setup.add("qv", quiver);
        }

        return setup;
    }

    private JsonArray itemsOf(ItemContainer container, int size)
    {
        JsonArray items = new JsonArray();
        Item[] containerItems = container == null ? new Item[0] : container.getItems();
        for (int slot = 0; slot < size; slot++)
        {
            Item slotItem = slot < containerItems.length ? containerItems[slot] : null;
            items.add(slotItem == null || slotItem.getId() <= 0
                ? JsonNull.INSTANCE
                : item(slotItem.getId(), slotItem.getQuantity()));
        }

        return items;
    }

    private JsonArray runePouch()
    {
        EnumComposition runeTypes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
        JsonArray runes = new JsonArray();
        for (int[] varbits : RUNE_POUCH_VARBITS)
        {
            int runeType = client.getVarbitValue(varbits[0]);
            int quantity = client.getVarbitValue(varbits[1]);
            int itemId = runeType > 0 && runeTypes != null ? runeTypes.getIntValue(runeType) : -1;
            runes.add(itemId > 0 && quantity > 0 ? item(itemId, quantity) : JsonNull.INSTANCE);
        }

        return runes;
    }

    private static JsonElement item(int id, int quantity)
    {
        JsonObject item = new JsonObject();
        item.addProperty("id", id);
        item.addProperty("q", quantity);
        return item;
    }

    private static class Snapshot
    {
        private final long timeMs;
        private final JsonObject setup;
        private final String setupText;

        private Snapshot(long timeMs, JsonObject setup, String setupText)
        {
            this.timeMs = timeMs;
            this.setup = setup;
            this.setupText = setupText;
        }
    }
}

package com.encryptiron.runs;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;

import javax.inject.Inject;

import com.encryptiron.rest.SendStatisticBoard;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Point;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

public class StatisticBoardReader
{
    private static final int MOST_COMPONENTS_PER_INTERFACE = 512;
    private static final int TICKS_TO_RECOGNISE_A_BOARD = 10;
    private static final Pattern PERSONAL_LINE = Pattern.compile("(?im)^\\s*(?:personal|fastest|best|your best)\\b");
    private static final Pattern TIME = Pattern.compile("\\d+(?::\\d{2}){1,2}(?:\\.\\d{1,2})?");
    private static final Pattern LINE_BREAK = Pattern.compile("(?i)<br\\s*/?>");
    private static final int FULLY_TRANSPARENT = 255;
    private static final int COVER_TO_TEXT_AREA = 9;
    private static final Set<Integer> NEVER_BOARDS = Set.of(InterfaceID.CHATBOX, InterfaceID.PM_CHAT, InterfaceID.CHATCHANNEL_CURRENT);

    @Inject
    private Client client;

    @Inject
    private SendStatisticBoard sendStatisticBoard;

    private final Map<Integer, Integer> ticksLeftToRecogniseByInterface = new HashMap<>();
    private final Set<Integer> openBoards = new HashSet<>();
    private final Map<Integer, String> lastSentBoardByInterface = new HashMap<>();
    private final Map<Integer, String> lastReadBoardByInterface = new HashMap<>();
    private final Map<Integer, Map<Widget, WidgetAppearance>> widgetAppearancesByInterface = new HashMap<>();
    private long boardReads;

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded widgetLoaded)
    {
        if (widgetLoaded.getGroupId() != client.getTopLevelInterfaceId() && !NEVER_BOARDS.contains(widgetLoaded.getGroupId()))
        {
            ticksLeftToRecogniseByInterface.put(widgetLoaded.getGroupId(), TICKS_TO_RECOGNISE_A_BOARD);
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged gameStateChanged)
    {
        if (gameStateChanged.getGameState() == GameState.LOGIN_SCREEN || gameStateChanged.getGameState() == GameState.HOPPING)
        {
            ticksLeftToRecogniseByInterface.clear();
            openBoards.clear();
            lastSentBoardByInterface.clear();
            lastReadBoardByInterface.clear();
            widgetAppearancesByInterface.clear();
        }
    }

    @Subscribe
    public void onGameTick(GameTick gameTick)
    {
        openBoards.removeIf(interfaceId -> client.getWidget(interfaceId, 0) == null);
        widgetAppearancesByInterface.keySet().retainAll(openBoards);
        lastReadBoardByInterface.keySet().retainAll(openBoards);
        for (int interfaceId : openBoards)
        {
            readBoard(interfaceId);
        }

        ticksLeftToRecogniseByInterface.keySet().removeAll(openBoards);
        ticksLeftToRecogniseByInterface.entrySet().removeIf(interfaceTicks -> {
            if (readBoard(interfaceTicks.getKey()))
            {
                openBoards.add(interfaceTicks.getKey());
                return true;
            }

            interfaceTicks.setValue(interfaceTicks.getValue() - 1);
            return interfaceTicks.getValue() <= 0;
        });
    }

    private boolean readBoard(int interfaceId)
    {
        Set<Widget> visited = Collections.newSetFromMap(new IdentityHashMap<>());
        List<Widget> widgetsInDrawOrder = new ArrayList<>();
        for (int componentId = 0; componentId < MOST_COMPONENTS_PER_INTERFACE; componentId++)
        {
            Widget widget = client.getWidget(interfaceId, componentId);
            if (widget != null && widget.getParentId() >>> 16 != interfaceId)
            {
                collect(widget, visited, widgetsInDrawOrder);
            }
        }

        if (widgetsInDrawOrder.stream().noneMatch(widget -> PERSONAL_LINE.matcher(textOf(widget)).find()))
        {
            widgetAppearancesByInterface.remove(interfaceId);
            return false;
        }

        long readNumber = ++boardReads;
        Map<Widget, WidgetAppearance> previousAppearances = widgetAppearancesByInterface.getOrDefault(interfaceId, Collections.emptyMap());
        Map<Widget, WidgetAppearance> appearances = new IdentityHashMap<>();
        List<Widget> textWidgets = new ArrayList<>();
        List<Widget> covers = new ArrayList<>();
        for (Widget widget : widgetsInDrawOrder)
        {
            if (widget.getCanvasLocation() == null || !isDrawn(widget))
            {
                continue;
            }

            String text = textOf(widget);
            WidgetAppearance appearance = previousAppearances.get(widget);
            if (appearance == null || !appearance.text.equals(text))
            {
                appearance = new WidgetAppearance(text, readNumber);
            }
            appearances.put(widget, appearance);

            if (widget.getType() == WidgetType.TEXT)
            {
                textWidgets.add(widget);
            }
            else if (canCover(widget))
            {
                covers.add(widget);
            }
        }
        widgetAppearancesByInterface.put(interfaceId, appearances);

        Map<String, BoardText> topmostTextByPosition = new HashMap<>();
        boolean hasPersonalLabel = false;
        boolean hasTime = false;
        for (Widget widget : textWidgets)
        {
            WidgetAppearance appearance = appearances.get(widget);
            if (isCoveredByNewerWidget(widget, appearance.readNumber, covers, appearances))
            {
                continue;
            }

            Point location = widget.getCanvasLocation();
            BoardText boardText = new BoardText(appearance.text, location.getX() + widget.getWidth() / 2, location.getY(), appearance.readNumber,
                widget.getTextColor(), backgroundOf(widget, covers));
            String position = boardText.x + "," + boardText.y;
            BoardText covered = topmostTextByPosition.get(position);
            if (covered == null || boardText.appearedOnRead >= covered.appearedOnRead)
            {
                topmostTextByPosition.put(position, boardText);
            }
        }

        List<BoardText> boardTexts = new ArrayList<>(topmostTextByPosition.values());
        boardTexts.removeIf(boardText -> boardText.text.isEmpty());
        for (BoardText boardText : boardTexts)
        {
            hasPersonalLabel |= PERSONAL_LINE.matcher(boardText.text).find();
            hasTime |= TIME.matcher(boardText.text).find();
        }

        if (!hasPersonalLabel || !hasTime)
        {
            widgetAppearancesByInterface.remove(interfaceId);
            return false;
        }

        boardTexts.sort(Comparator.comparingInt((BoardText boardText) -> boardText.y)
            .thenComparingInt(boardText -> boardText.x)
            .thenComparing(boardText -> boardText.text));

        JsonArray texts = new JsonArray();
        for (BoardText boardText : boardTexts)
        {
            JsonObject entry = new JsonObject();
            entry.addProperty("text", boardText.text);
            entry.addProperty("x", boardText.x);
            entry.addProperty("y", boardText.y);
            entry.addProperty("c", boardText.textColor);
            if (boardText.background != null)
            {
                entry.addProperty("bg", boardText.background);
            }
            texts.add(entry);
        }

        String board = boardContent(boardTexts);
        boolean unchangedSinceLastRead = board.equals(lastReadBoardByInterface.put(interfaceId, board));
        if (unchangedSinceLastRead && !board.equals(lastSentBoardByInterface.get(interfaceId)))
        {
            lastSentBoardByInterface.put(interfaceId, board);
            sendStatisticBoard.send(texts);
        }

        return true;
    }

    private static String boardContent(List<BoardText> boardTexts)
    {
        List<String> content = new ArrayList<>();
        for (BoardText boardText : boardTexts)
        {
            content.add(boardText.text + "|" + boardText.textColor + "|" + boardText.background);
        }
        Collections.sort(content);
        return String.join("\n", content);
    }

    private static class BoardText
    {
        private final String text;
        private final int x;
        private final int y;
        private final long appearedOnRead;
        private final int textColor;
        private final String background;

        private BoardText(String text, int x, int y, long appearedOnRead, int textColor, String background)
        {
            this.text = text;
            this.x = x;
            this.y = y;
            this.appearedOnRead = appearedOnRead;
            this.textColor = textColor;
            this.background = background;
        }
    }

    private static class WidgetAppearance
    {
        private final String text;
        private final long readNumber;

        private WidgetAppearance(String text, long readNumber)
        {
            this.text = text;
            this.readNumber = readNumber;
        }
    }

    private static String textOf(Widget widget)
    {
        return widget.getType() != WidgetType.TEXT || widget.getText() == null
            ? ""
            : Text.removeTags(LINE_BREAK.matcher(widget.getText()).replaceAll("\n")).replace((char) 0xA0, ' ').trim();
    }

    private static boolean canCover(Widget widget)
    {
        switch (widget.getType())
        {
            case WidgetType.LAYER:
                return true;
            case WidgetType.RECTANGLE:
                return widget.isFilled() && widget.getOpacity() == 0;
            case WidgetType.GRAPHIC:
                return widget.getSpriteId() >= 0 && widget.getOpacity() == 0;
            default:
                return false;
        }
    }

    private static String backgroundOf(Widget widget, List<Widget> covers)
    {
        Rectangle bounds = widget.getBounds();
        int centreX = bounds.x + bounds.width / 2;
        int centreY = bounds.y + bounds.height / 2;
        Widget background = null;
        long backgroundArea = Long.MAX_VALUE;
        for (Widget cover : covers)
        {
            Rectangle coverBounds = cover.getBounds();
            long area = (long) coverBounds.width * coverBounds.height;
            if (cover.getType() != WidgetType.LAYER && area < backgroundArea && coverBounds.contains(centreX, centreY))
            {
                background = cover;
                backgroundArea = area;
            }
        }

        if (background == null)
        {
            return null;
        }

        return background.getType() == WidgetType.GRAPHIC
            ? "s" + background.getSpriteId()
            : "r" + Integer.toHexString(background.getTextColor());
    }

    private static boolean isCoveredByNewerWidget(Widget widget, long appearedOnRead, List<Widget> covers,
        Map<Widget, WidgetAppearance> appearances)
    {
        Set<Widget> ancestors = Collections.newSetFromMap(new IdentityHashMap<>());
        for (Widget ancestor = widget.getParent(); ancestor != null; ancestor = ancestor.getParent())
        {
            ancestors.add(ancestor);
        }

        Rectangle bounds = widget.getBounds();
        long textArea = (long) bounds.width * bounds.height;
        int centreX = bounds.x + bounds.width / 2;
        int centreY = bounds.y + bounds.height / 2;
        for (Widget cover : covers)
        {
            Rectangle coverBounds = cover.getBounds();
            if (appearances.get(cover).readNumber > appearedOnRead
                && !ancestors.contains(cover)
                && (long) coverBounds.width * coverBounds.height >= COVER_TO_TEXT_AREA * textArea
                && coverBounds.contains(centreX, centreY))
            {
                return true;
            }
        }

        return false;
    }

    private static boolean isDrawn(Widget widget)
    {
        if (widget.isHidden() || widget.getOpacity() >= FULLY_TRANSPARENT)
        {
            return false;
        }

        Rectangle bounds = widget.getBounds();
        for (Widget ancestor = widget.getParent(); ancestor != null; ancestor = ancestor.getParent())
        {
            if (ancestor.getScrollHeight() > 0)
            {
                return true;
            }

            if (!bounds.intersects(ancestor.getBounds()))
            {
                return false;
            }
        }

        return true;
    }

    private static void collect(Widget widget, Set<Widget> visited, List<Widget> widgetsInDrawOrder)
    {
        if (widget == null || !visited.add(widget))
        {
            return;
        }

        widgetsInDrawOrder.add(widget);
        collectAll(widget.getStaticChildren(), visited, widgetsInDrawOrder);
        collectAll(widget.getDynamicChildren(), visited, widgetsInDrawOrder);
        collectAll(widget.getNestedChildren(), visited, widgetsInDrawOrder);
    }

    private static void collectAll(Widget[] children, Set<Widget> visited, List<Widget> widgetsInDrawOrder)
    {
        if (children == null)
        {
            return;
        }

        for (Widget child : children)
        {
            collect(child, visited, widgetsInDrawOrder);
        }
    }
}

package com.encryptiron.runs;

import java.util.ArrayList;
import java.util.List;

import com.google.gson.JsonArray;

class TimeSpans
{
    private static final long LONGEST_GAP_WITHIN_ONE_SPAN_MS = 2000;

    private final List<long[]> spans = new ArrayList<>();

    void add(long timeMs)
    {
        if (!spans.isEmpty())
        {
            long[] lastSpan = spans.get(spans.size() - 1);
            if (timeMs - lastSpan[1] <= LONGEST_GAP_WITHIN_ONE_SPAN_MS)
            {
                lastSpan[1] = Math.max(lastSpan[1], timeMs);
                return;
            }
        }

        spans.add(new long[] {timeMs, timeMs});
    }

    void dropEndedBefore(long timeMs)
    {
        spans.removeIf(span -> span[1] < timeMs);
    }

    boolean isEmpty()
    {
        return spans.isEmpty();
    }

    JsonArray toOffsetsWithin(long fromMs, long toMs)
    {
        JsonArray offsets = new JsonArray();
        for (long[] span : spans)
        {
            if (span[1] < fromMs || span[0] > toMs)
            {
                continue;
            }

            JsonArray spanOffsets = new JsonArray();
            spanOffsets.add(Math.max(span[0], fromMs) - toMs);
            spanOffsets.add(Math.min(span[1], toMs) - toMs);
            offsets.add(spanOffsets);
        }

        return offsets;
    }
}

